# Generated by package/dev/sync_core.py from tools/rbs_start_prior.py -- do not edit here.
#!/usr/bin/env python3
"""Self-trained, genome-specific RBS start prior -- gating check.

Prodigal learns its ribosome-binding-site motif *on the genome being annotated*.
Our SD channel instead learns one universal motif across 604 training genomes,
and RBS usage varies enormously by taxon -- which is a candidate explanation for
why ``--enable-sd-channel`` came out neutral-to-negative on the START channel.

This builds the Prodigal-style version with **no retraining and no reference**:

  1. take our own predicted starts on this genome (they are ~92% correct, and
     nothing here consults the reference),
  2. count Prodigal's 28 RBS bins over their upstream regions,
  3. count the same bins over the ALTERNATIVE in-frame starts of those same ORFs
     -- the competitors we currently choose between,
  4. score(bin) = log( P_pred(bin) / P_alt(bin) ), a self-trained log-odds.

Then it asks the only question that gates the whole idea: **at the loci where we
picked the wrong start, does this score prefer the correct one?** If it does not,
a decode-side RBS prior cannot fix the 217 start-site errors and the idea dies
here, cheaply.

Usage::

    python tools/rbs_start_prior.py --genome-fasta <fna> --reference-gff <gff> \
      --predictions-gff3 <preds> --seqid NC_000913.3 \
      --out results/rbs_prior/k12_bins.tsv
"""
from __future__ import annotations

import argparse
import math
import sys
from collections import Counter
from pathlib import Path
from typing import Dict, List, Optional, Sequence, Tuple

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    pass

from .prodigal_rbs_bins import prodigal_rbs_bin_from_upstream  # noqa: E402
from .viterbi_decode import VALID_START_SET, VALID_STOP_SET  # noqa: E402

# Defined here rather than imported: pulling these from detect_container_pseudogenes
# drags in pseudogene_frame_utils -> export_nn_probs_tracks, and this module is
# imported by the decoder, which must stay light and portable.
_COMPLEMENT = str.maketrans("ACGTNacgtn", "TGCANtgcan")


def revcomp(seq: str) -> str:
    return seq.translate(_COMPLEMENT)[::-1]


def load_fasta(path: Path) -> Dict[str, str]:
    seqs: Dict[str, str] = {}
    name = None
    buf: List[str] = []
    with path.open() as fh:
        for line in fh:
            if line.startswith(">"):
                if name is not None:
                    seqs[name] = "".join(buf)
                name, buf = line[1:].split()[0], []
            else:
                buf.append(line.strip())
    if name is not None:
        seqs[name] = "".join(buf)
    return seqs

UPSTREAM_NT = 45
Feat = Tuple[str, int, int, str]


def upstream_region(seq: str, lo: int, hi: int, strand: str, *, n: int = UPSTREAM_NT) -> Optional[str]:
    """The n bases 5' of the start codon, oriented 5'->3' on the gene's strand."""
    if strand == "+":
        a, b = lo - n, lo
        if a < 0 or b > len(seq):
            return None
        return seq[a:b].upper()
    a, b = hi, hi + n
    if a < 0 or b > len(seq):
        return None
    return revcomp(seq[a:b]).upper()


def rbs_bin(seq: str, lo: int, hi: int, strand: str) -> int:
    region = upstream_region(seq, lo, hi, strand)
    return 0 if region is None else prodigal_rbs_bin_from_upstream(region)


def alt_starts(seq: str, lo: int, hi: int, strand: str, *, min_nt: int = 90
               ) -> List[Tuple[int, int]]:
    """Other in-frame starts sharing this ORF's stop codon, in forward coords.

    Walks 5' from the codon adjacent to the stop and halts at the first in-frame
    stop, so the candidate set is exactly the ORF the decoder had to choose a
    start within -- both shorter and longer than the one we picked.
    """
    out: List[Tuple[int, int]] = []
    if strand == "+":
        # stop occupies [hi-3, hi); codons walk 5' from hi-6
        for i in range(hi - 6, -1, -3):
            cod = seq[i:i + 3]
            if cod in VALID_STOP_SET:
                break
            if cod in VALID_START_SET and (hi - i) >= min_nt and i != lo:
                out.append((i, hi))
    else:
        # stop occupies [lo, lo+3); start codons are revcomp(seq[p-3:p])
        for p in range(lo + 6, len(seq) + 1, 3):
            cod = revcomp(seq[p - 3:p])
            if cod in VALID_STOP_SET:
                break
            if cod in VALID_START_SET and (p - lo) >= min_nt and p != hi:
                out.append((lo, p))
    return out


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--genome-fasta", type=Path, required=True)
    ap.add_argument("--reference-gff", type=Path, required=True)
    ap.add_argument("--predictions-gff3", type=Path, required=True)
    ap.add_argument("--seqid", type=str, required=True)
    ap.add_argument("--out", type=Path, required=True)
    args = ap.parse_args()

    from .fp_coding_potential import parse_gff, stop_key
    seq = load_fasta(args.genome_fasta)[args.seqid].upper()
    ref = parse_gff(args.reference_gff, ["CDS"], args.seqid)
    pred = parse_gff(args.predictions_gff3, ["CDS"], args.seqid)

    # ---- 1-3: self-training. No reference is consulted in this block. ----
    pred_bins = Counter(rbs_bin(seq, p[1], p[2], p[3]) for p in pred)
    alt_bins: Counter = Counter()
    for p in pred:
        for a, b in alt_starts(seq, p[1], p[2], p[3]):
            alt_bins[rbs_bin(seq, a, b, p[3])] += 1

    npred = max(sum(pred_bins.values()), 1)
    nalt = max(sum(alt_bins.values()), 1)
    score: Dict[int, float] = {}
    for b in range(28):
        pp = (pred_bins.get(b, 0) + 1) / (npred + 28)
        pa = (alt_bins.get(b, 0) + 1) / (nalt + 28)
        score[b] = math.log(pp / pa)

    args.out.parent.mkdir(parents=True, exist_ok=True)
    with args.out.open("w") as fh:
        fh.write("bin\tn_predicted_starts\tn_alt_starts\tfreq_pred\tfreq_alt\tlog_odds\n")
        for b in range(28):
            fh.write(f"{b}\t{pred_bins.get(b,0)}\t{alt_bins.get(b,0)}"
                     f"\t{pred_bins.get(b,0)/npred:.5f}\t{alt_bins.get(b,0)/nalt:.5f}"
                     f"\t{score[b]:+.4f}\n")

    print(f"self-trained on {npred} predicted starts vs {nalt} alternative in-frame starts")
    top = sorted(score.items(), key=lambda kv: -kv[1])[:6]
    bot = sorted(score.items(), key=lambda kv: kv[1])[:3]
    print("  most start-like bins : " + ", ".join(f"{b}({s:+.2f})" for b, s in top))
    print("  least start-like     : " + ", ".join(f"{b}({s:+.2f})" for b, s in bot))

    # ---- 4: the gating question. Reference used for EVALUATION only. ----
    refset, refstops = set(ref), {stop_key(r): r for r in ref}
    wrong = [(p, refstops[stop_key(p)]) for p in pred
             if p not in refset and stop_key(p) in refstops]
    better = worse = tie = 0
    for p, r in wrong:
        sp = score[rbs_bin(seq, p[1], p[2], p[3])]
        sr = score[rbs_bin(seq, r[1], r[2], r[3])]
        if sr > sp:
            better += 1
        elif sr < sp:
            worse += 1
        else:
            tie += 1
    n = max(len(wrong), 1)
    print(f"\nGATING CHECK -- {len(wrong)} start-site errors (our start != reference start)")
    print(f"  RBS score prefers the CORRECT start : {better:>4}  ({better/n:.1%})")
    print(f"  RBS score prefers OUR wrong start   : {worse:>4}  ({worse/n:.1%})")
    print(f"  tie (same bin)                      : {tie:>4}  ({tie/n:.1%})")
    decisive = better + worse
    if decisive:
        print(f"  among decisive cases: {better}/{decisive} = {better/decisive:.1%} correct")

    # Reference check: does the prior separate correct calls from their alternatives?
    ok = [p for p in pred if p in refset]
    agree = tot = 0
    for p in ok[:2000]:
        sp = score[rbs_bin(seq, p[1], p[2], p[3])]
        alts = alt_starts(seq, p[1], p[2], p[3])
        if not alts:
            continue
        tot += 1
        if all(sp >= score[rbs_bin(seq, a, b, p[3])] for a, b in alts):
            agree += 1
    if tot:
        print(f"\nsanity: on CORRECT calls, the true start is top-ranked by RBS in "
              f"{agree}/{tot} ({agree/tot:.1%}) of ORFs with alternatives")


if __name__ == "__main__":
    main()
